mapper.select:
SELECT d.*,o.type from s_order o LEFT JOIN oms_order_detail d on d.order_id = o.id LEFT JOIN c_customer c on c.id = o.customer_id where o.type in (0,2) and d.state in (0, 1, 2) and o.state not in(3,4) and d.shop_id = #{shopId} AND d.start_time >= #{startDateTime} AND d.end_time <= #{endDateTime}
AND c.phone LIKE CONCAT('%',#{customerPhone},'%')
ORDER BY d.start_time ASC
